{"path": "/work/calc.py", "content": """"Small statistics helpers."""


def mean(xs):
    """Return the arithmetic mean of a non-empty sequence of numbers."""
    xs = list(xs)
    if not xs:
        raise ValueError("mean() requires at least one value")
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of a non-empty sequence of numbers.

    For an even number of values the median is the average of the two
    middle values.
    """
    xs = sorted(xs)
    n = len(xs)
    if n == 0:
        raise ValueError("median() requires at least one value")
    mid = n // 2
    if n % 2 == 1:
        return xs[mid]
    return (xs[mid - 1] + xs[mid]) / 2
"}

