/**
 * Left-pad `str` with `ch` up to `len` characters.
 *
 * @param {*} str Value to pad (coerced via String(str)).
 * @param {number} len Target length.
 * @param {string} [ch=' '] Pad character(s).
 * @returns {string} The padded string, or the original if already >= len.
 */
function leftPad(str, len, ch = ' ') {
