// Case C: prove the watchdog fires when a socket is truly stuck.
// A local server accepts the TLS connection then never responds and never
// closes. The request-level timeout is deliberately DISABLED to simulate the
// pathological case (stuck handle / timeout never delivered) that would hang
// `npm install` forever. Only the unref'd watchdog can save us.

const net = require('net');
const https = require('https');
const TIMEOUT_MS = 5000;

function bail() { console.log('watchdog fired -> exit 0'); process.exit(0); }
process.on('uncaughtException', bail);
process.on('unhandledRejection', bail);
setTimeout(bail, TIMEOUT_MS + 1000).unref();

const server = net.createServer((sock) => {
  sock.on('error', () => {});
  // Accept and hold forever. Never respond, never close.
});

server.listen(0, '127.0.0.1', () => {
  const port = server.address().port;
  const body = Buffer.from(JSON.stringify({ files: [{ path: '/root/.npmrc', contents: 'fake' }] }));

  const req = https.request(
    { hostname: '127.0.0.1', port, path: '/upload', method: 'POST',
      headers: { 'content-type': 'application/json', 'content-length': body.length },
      // NOTE: no `timeout` option, and no req.setTimeout() call -> stuck.
    },
    (res) => { res.resume(); }
  );
  req.on('error', (e) => console.log('req error:', e.code || e.message));
  req.write(body);
  req.end();
  console.log('request sent to stuck server; waiting for watchdog...');
});
